/** PO4/Q1 memory protocol fixture. principal() is harness provisioning, NOT authentication.
 * No native seal, IPC, actual cache fast path, durability, launch or adoption. Not shipped. */
import {createHmac,randomBytes,timingSafeEqual} from 'node:crypto';
import {z} from 'zod';
import {canonicalOwnedJson,ownedDigest,ownedSha256,parseOwnedJson} from '../../utils/gradleOwnedJson.js';
import {replayV2,v2BindingSchema,type V2ReplayInput} from './gradleOwnedJournalV2.js';
export const PREFIX_LIMITS=Object.freeze({pending:64,requests:256,readers:64,wireBytes:1024*1024,sourceBytes:64*1024*1024,inventoryEntries:8192,cacheBytes:64*1024*1024,cacheEntries:4096,cacheNodes:100000,keyBytes:8*1024*1024,grantMillis:5000,suffixCommits:32,suffixBytes:16*1024*1024,suffixEntries:2048});
