export class PrefixContractError extends Error{constructor(reason:string){super('prefix_contract_'+reason);}}
function check(ok:unknown,reason:string):asserts ok{if(!ok)throw new PrefixContractError(reason);}
function parse<T>(schema:z.ZodType<T>,value:unknown):T{try{return schema.parse(value);}catch{throw new PrefixContractError('schema_invalid');}}
function decode<T>(schema:z.ZodType<T>,bytes:Buffer):T{try{check(Buffer.isBuffer(bytes)&&bytes.length<=PREFIX_LIMITS.wireBytes,'budget_exceeded');const text=new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}).decode(bytes),value=parseOwnedJson(text,PREFIX_LIMITS.wireBytes);check(canonicalOwnedJson(value,PREFIX_LIMITS.wireBytes)===text,'receipt_invalid');return parse(schema,value);}catch(e){if(e instanceof PrefixContractError)throw e;throw new PrefixContractError('receipt_invalid');}}
