export type PrefixHandle=Readonly<{kind:'prefix-contract-handle'}>;
type Phase='active'|'completing'|'decision-recorded'|'delivering'|'released'|'expired'|'cancelled';
type SnapshotSeal={identity:Identity;wire:z.infer<typeof snapshotSchema>};
type Snapshot=SnapshotSeal & {input:V2ReplayInput;inventory:Map<string,{sha256:string;size:number}>;bytes:number};
type Proof={snapshot:Snapshot;key:string};
type Reader={role:'reader';peer:z.infer<typeof readerSchema>;sequence:number;lastGrant:number;pending?:{request:z.infer<typeof requestSchema>;started:number;accepted:boolean;response?:Buffer};cache?:Proof;stopped:boolean};
type Gate={kind:'checkpoint'|'authority';pin:Pin;version:number;ref:string};
type Pin={reader:Reader;request:z.infer<typeof requestSchema>;grant:z.infer<typeof grantSchema>;snapshot:SnapshotSeal;phase:Phase;started:number;reuse:boolean;prefix?:Proof;candidate?:PrefixHandle;checkpoint?:Gate;authority?:Gate;complete?:z.infer<typeof completeSchema>;receipt?:z.infer<typeof receiptSchema>;published:boolean};
type HandleData={kind:'ticket'|'candidate'|'delivery';pin:Pin};
export interface PrefixContractConfig{identity:Identity;keyId:string;key:Buffer;providerNow:()=>number;readerNow:()=>number;supported?:boolean;approved?:boolean;limits?:Partial<Record<keyof typeof PREFIX_LIMITS,number>>}
