 #source?:Snapshot;#owner=true;#available=true;#phase:'idle'|'draining'|'retired'='idle';#cp:'synced'|'unavailable'|'sync-incomplete'|'rollback'|'tail-unknown'='synced';#cpVersion=0;#authority:'current'|'expired'|'revoked'='current';#authVersion=0;#providerTime=0;#readerTime=0;#sequence=0;#decision=0;
